  <script>
    (()=>{
      const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
      const toast=$('#toast'); let toastTimer;
      function showToast(title,text){$('#toastTitle').textContent=title;$('#toastText').textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2800)}
      function openModal(id){const modal=$(id);if(!modal)return;modal.classList.add('open');document.body.style.overflow='hidden'}
      function closeModals(){ $$('.modal.open').forEach(m=>m.classList.remove('open'));document.body.style.overflow='' }
      $$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModals()})); $$('[data-close]').forEach(b=>b.addEventListener('click',closeModals)); document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModals()});
      const mobileMenu=$('#mobileMenu'); $('#menuOpen')?.addEventListener('click',()=>{mobileMenu.classList.add('open');mobileMenu.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}); $('#menuClose')?.addEventListener('click',()=>{mobileMenu.classList.remove('open');mobileMenu.setAttribute('aria-hidden','true');document.body.style.overflow=''});
      ['#invoiceHero','#invoiceButton','#invoiceSummary'].forEach(id=>$(id)?.addEventListener('click',()=>showToast('Factura este pregătită','NVF-1842.pdf a fost generată pentru descărcare.')));
      $('#downloadAll')?.addEventListener('click',()=>showToast('Arhivă generată','Biletele și factura au fost grupate într-un singur fișier.'));
      $('#shareOrder')?.addEventListener('click',()=>showToast('Link copiat','Linkul securizat al comenzii a fost copiat.'));
      $$('[data-wallet]').forEach(b=>b.addEventListener('click',()=>showToast('Adăugat în Wallet','Permisul digital a fost salvat pe dispozitiv.')));
      $$('[data-ticket]').forEach(b=>b.addEventListener('click',()=>{$('#ticketName').textContent=b.dataset.ticket;openModal('#ticketModal')}));
      ['#openSupport','#sideSupport'].forEach(id=>$(id)?.addEventListener('click',()=>openModal('#supportModal')));
      $('#requestRefund')?.addEventListener('click',()=>openModal('#refundModal'));
      $('#changeDate')?.addEventListener('click',()=>showToast('Calendar deschis','Poți alege o altă dată disponibilă din pagina biletului.'));
      $('#editPeople')?.addEventListener('click',()=>showToast('Editare participanți','Numele pot fi modificate din detaliul fiecărui bilet.'));
      $('#notificationButton')?.addEventListener('click',()=>showToast('Nicio alertă nouă','Comanda este activă și nu necesită acțiuni.'));
      $('#supportForm')?.addEventListener('submit',e=>{e.preventDefault();closeModals();showToast('Solicitare trimisă','Echipa Nordvale va răspunde pe email.')});
      $('#sendRefund')?.addEventListener('click',()=>{closeModals();showToast('Cerere înregistrată','Vei primi rezultatul verificării în maximum 2 zile lucrătoare.')});
      if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(16px)'},{opacity:1,transform:'translateY(0)'}],{duration:480,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});observer.unobserve(entry.target)}}),{threshold:.08});$$('.panel,.summary-card,.support-card').forEach(el=>observer.observe(el))}
    })();
  </script>
  <script>
  (function(){
    function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
    var a = nvAuth();
    if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
    var AH = { 'Authorization':'Bearer '+a.token };
    function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
    function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
    function esc(s){ var d=document.createElement('div'); d.textContent=(s==null?'':String(s)); return d.innerHTML; }
    function money(v,c){ if(v==null||v==='') return ''; c=(c||'lei'); if(String(c).toLowerCase()==='ron')c='lei'; return new Intl.NumberFormat('ro-RO').format(Math.round(Number(v)))+' '+c; }
    function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
    function fmtDate(iso){ if(!iso)return ''; var d=new Date(iso); if(isNaN(d))return ''; return d.toLocaleDateString('ro-RO',{day:'2-digit',month:'short',year:'numeric'}); }
    function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; } }
    document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });
    hydrateUser(a.user);
    api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); } });

    var id=new URLSearchParams(location.search).get('id');
    var bc=document.querySelector('.breadcrumb span:last-child');
    if(!id) return;
    api('acc-order&id='+encodeURIComponent(id)).then(function(d){ if(!(d&&d.success&&d.data))return; var o=d.data;
      if(bc)bc.textContent='#'+o.order_number;
      var pills=document.querySelectorAll('.hero-meta .hero-pill'); if(pills[0])pills[0].textContent='● '+(o.is_paid?'Plătită':(o.status||'')); if(pills[1])pills[1].textContent='#'+o.order_number; if(pills[2]&&o.created_at)pills[2].textContent=fmtDate(o.created_at);
      var tot=document.querySelector('.hero-total strong'); if(tot)tot.textContent=money(o.total,o.currency);
      var hcg=document.querySelectorAll('.hero-card-grid div b'); if(hcg[0])hcg[0].textContent=(o.tickets_count||0)+' bilete'; if(hcg[1]&&o.event)hcg[1].textContent=o.event;
      var sumTotal=document.querySelector('.sum-row.total strong'); if(sumTotal)sumTotal.textContent=money(o.total,o.currency);
      var tickets=o.tickets||[]; var grid=document.querySelector('.ticket-grid'); if(grid&&tickets.length){ grid.innerHTML=tickets.map(function(t){ var nm=t.seat_label||t.type||'Bilet'; return '<article class="ticket"><small>'+esc(t.type||'Bilet')+' · '+esc(t.status||'activ')+'</small><strong>'+esc(nm)+'</strong><span>'+esc(t.code||'')+'</span><div class="ticket-actions"><a class="mini-btn acid" href="/cont/bilet?code='+encodeURIComponent(t.code||'')+'">Detaliu</a></div></article>'; }).join(''); }
    });
  })();
  </script>
